import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("should charge a premium of 5 G for an empty item list");
    it.todo("should charge 105 G for a single plain sword (100 G base + 5 G fee)");
    it.todo("should charge 65 G for a single plain amulet");
    it.todo("should charge 85 G for a single plain staff");
    it.todo("should charge 45 G for a single plain potion");
    it.todo("should charge 30 G for a single rune (25 G base + 5 G fee)");
    it.todo("should charge 30 G for a single moonstone");
    it.todo("should sum the base premiums of several different items");
  });

  describe("quote — component blocks", () => {
    it.todo("should charge 50 G base premium for 2 runes (no block)");
    it.todo("should charge 60 G base premium for 3 runes (block applies)");
    it.todo("should charge 100 G base premium for 4 runes (block requires exactly 3)");
    it.todo("should charge 175 G base premium for 7 runes (no block)");
    it.todo("should charge 75 G base premium for 2 runes and 1 moonstone (different types do not form a block)");
    it.todo("should charge 120 G base premium for 3 runes and 3 moonstones (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("should add 50 % of the item's base premium for a cursed item");
    it.todo("should add 30 % of the item's base premium for enchantment 5");
    it.todo("should not add the high-enchantment surcharge for enchantment 4");
    it.todo("should add both surcharges for a cursed item with enchantment 5");
    it.todo("should apply the cursed surcharge only to the cursed item on a multi-item policy (cursed sword + plain amulet → 210 G before fee)");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("should add 10 % of the policy base premium as first insurance surcharge to every quote");
    it.todo("should subtract 20 % of the policy base premium for a customer with 2 years with MHPCO");
    it.todo("should not apply the loyalty discount for a customer with 1 year with MHPCO");
    it.todo("should subtract 15 % of the policy base premium for each quote after the customer's first");
    it.todo("should not apply the follow-up discount to the customer's first quote");
  });

  describe("quote — rounding", () => {
    it.todo("should round a premium of 197.5 G up to 198 G");
    it.todo("should keep intermediate amounts as fractions and round only the final premium");
  });

  describe("quote — integration examples", () => {
    it.todo("should charge 165 G for a newcomer's cursed sword (0 years, first contract)");
    it.todo("should charge 160 G for the second quote of a 3-year customer insuring a cursed sword with enchantment 7");
  });

  describe("quote — errors", () => {
    it.todo("should reject a quote containing an item with an unknown type");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("should pay 400 G for 500 G damage to a plain steel sword with enchantment 3 (deductible 100 G)");
    it.todo("should pay 100 G for 200 G damage to a rune (no enchantment level or material)");
    it.todo("should apply the 100 G deductible once per damage entry (sword 500 G + amulet 300 G → 600 G)");
  });

  describe("claim — special clauses", () => {
    it.todo("should pay 50 % of the damage before the deductible for enchantment 8 (dragon sword, 1000 G → 400 G)");
    it.todo("should pay 400 G for a steel sword with enchantment 9 damaged by 1000 G (50 % rule only)");
    it.todo("should pay 700 G for a dragon-material sword with enchantment 5 damaged by 800 G (full reimbursement, then deductible)");
    it.todo("should let the 50 % rule win over dragon material (dragon sword, enchantment 9, 1000 G → 400 G)");
  });

  describe("claim — cap", () => {
    it.todo("should report a remaining cap of twice the insurance sum minus the payout");
    it.todo("should base the cap on the sum of the items' unmodified insurance values (sword + amulet → cap 3200 G)");
    it.todo("should not raise the cap through premium modifiers (cursed sword → cap 2000 G)");
    it.todo("should not reduce the insurance sum through a component block discount (sword + 3 runes → insurance sum 1750 G)");
    it.todo("should carry the cap across successive claims (two 1500 G claims on a sword → 1400 G then 600 G)");
    it.todo("should report a remaining cap of 0 G once the cap is exhausted");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("should insure two swords with an insurance sum of 2000 G and a cap of 4000 G");
    it.todo("should treat two damage entries of the same item type as separate damages with their own deductible");
  });

  describe("claim — rounding", () => {
    it.todo("should round a payout of 350.5 G down to 350 G");
  });

  describe("claim — errors", () => {
    it.todo("should reject a claim whose damage entry references an item not covered by the policy");
    it.todo("should reject a claim whose damage entry references an unknown item type");
    it.todo("should reject a claim with more damage entries of a type than the policy insures");
    it.todo("should reject a claim with a negative damage amount");
  });

  describe("scenario processing", () => {
    it.todo("should return one result per step in the same order as the input steps");
    it.todo("should resolve a claim's policy field to the quote step at that zero-based index");
  });
});

